<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {state,init,save,remove,isDemo,resetDemo} from './store.js';
import {features,categoryIcons,milestoneGroups,dateKey,dateOf,addDays,monthDate,ageMonths,ageLabel,reference,cents,period,ledgerStats,toothInfo} from './domain.js';
import Calendar from './Calendar.vue';
import GrowthChart from './GrowthChart.vue';
import CuteIcon from './CuteIcon.vue';
const today=dateKey(),route=ref(location.hash.replace('#/','')||'home'),modal=ref(null),form=ref({}),busy=ref(false),formError=ref(''),notice=ref('');
const mealDate=ref(today),mealWeek=ref(true),todoDate=ref(today),showTodoCalendar=ref(false),growthType=ref('height'),ledgerMode=ref('month'),ledgerAnchor=ref(today),customStart=ref(monthDate(today,-1)),customEnd=ref(today),ledgerType=ref('expense'),milestoneGroup=ref('全部'),foodFilter=ref('all'),vaccineFilter=ref('all');
const records=kind=>state.records.filter(x=>x.kind===kind);
const profile=computed(()=>records('profile')[0]||{name:'宝宝',birth:'',sex:'girl'});
const growth=computed(()=>records('growth').sort((a,b)=>b.day.localeCompare(a.day)||a.id.localeCompare(b.id)));
const latest=computed(()=>growth.value[0]);
const milestones=computed(()=>records('milestone').filter(x=>milestoneGroup.value==='全部'||x.group===milestoneGroup.value));
const doneMilestones=computed(()=>records('milestone').filter(x=>x.day));
const meal=computed(()=>records('meal').find(x=>x.day===mealDate.value));
const foods=computed(()=>records('food').filter(x=>foodFilter.value==='all'||x.status===foodFilter.value));
const pendingVaccines=computed(()=>records('vaccine').filter(x=>x.status==='pending'));
const vaccines=computed(()=>records('vaccine').filter(x=>vaccineFilter.value==='all'||x.status===vaccineFilter.value).sort((a,b)=>(a.status===b.status?0:a.status==='pending'?-1:1)||a.day.localeCompare(b.day)));
const teeth=computed(()=>records('tooth').sort((a,b)=>a.day.localeCompare(b.day)));
const cats=computed(()=>records('category'));
const formCats=computed(()=>cats.value.filter(x=>x.type===form.value.type));
const accountingPeriod=computed(()=>period(ledgerMode.value,ledgerAnchor.value,customStart.value,customEnd.value));
const accountingValid=computed(()=>accountingPeriod.value.a<=accountingPeriod.value.b);
const stats=computed(()=>ledgerStats(records('ledger'),accountingPeriod.value));
const ledgerItems=computed(()=>records('ledger').filter(x=>x.day>=accountingPeriod.value.a&&x.day<=accountingPeriod.value.b).sort((a,b)=>b.day.localeCompare(a.day)));
const ranking=computed(()=>{const grouped=new Map();ledgerItems.value.filter(x=>x.type===ledgerType.value).forEach(x=>{const k=x.categoryName;const g=grouped.get(k)||{name:k,icon:x.icon,sum:0};g.sum+=x.cents;grouped.set(k,g);});return [...grouped.values()].sort((a,b)=>b.sum-a.sum);});
const title=computed(()=>features.find(x=>x[0]===route.value)?.[2]||({settings:'宝宝档案',categories:'分类管理'}[route.value]||'成长手记'));
const todayTodos=computed(()=>todosOn(today));
const todoProgress=computed(()=>todayTodos.value.length?Math.round(todayTodos.value.filter(x=>x.done).length/todayTodos.value.length*100):0);
const money=n=>(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const pretty=s=>s?new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(dateOf(s)):'';
const uid=()=>crypto.randomUUID();
let toastTimer;
function toast(s){notice.value=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.value='',3000);}
function routeChanged(){const r=location.hash.replace('#/','')||'home';route.value=r;modal.value=null;window.scrollTo({top:0});}
function followLink(e){const a=e.target.closest('a');if(a?.getAttribute('href')?.startsWith('#/')){e.preventDefault();location.hash=a.getAttribute('href');}}
function go(r){location.hash=r==='home'?'#/':'#/'+r;}
function back(){go(route.value==='categories'?'ledger':'home');}
function todosOn(day){return records('todo').filter(x=>x.day===day).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));}
function open(kind,record){formError.value='';const defaults={profile:{name:'',birth:today,sex:'girl'},growth:{day:today,height:'',weight:'',note:''},meal:{day:mealDate.value,breakfast:'',lunch:'',dinner:'',fruit:''},food:{day:today,name:'',status:'safe',note:''},ledger:{day:today,type:'expense',category:'',amount:'',note:''},category:{name:'',icon:'🍼',type:'expense'},todo:{day:todoDate.value,name:'',time:'09:00',done:false,note:''},vaccine:{name:'',day:today,status:'pending',given:'',note:''},tooth:{day:today,number:'71',note:''},milestone:{name:'',group:'大运动',day:'',custom:true,note:''}};
 form.value={...defaults[kind],...(record||{})};if(kind==='ledger'&&record)form.value.amount=(record.cents/100).toFixed(2);if(kind==='meal'){form.value.id='meal-'+form.value.day;}modal.value={kind,existing:!!record?.id};nextTick(()=>document.querySelector('.dialog input')?.focus());}
function close(){if(!busy.value)modal.value=null;}
function editProfile(){open('profile',records('profile')[0]);}
function askDelete(record){modal.value={kind:'delete',record};formError.value='';}
async function confirmDelete(){busy.value=true;try{await remove(modal.value.record.id);modal.value=null;toast('已删除');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
function validate(f,kind){if(['profile','food','category','todo','vaccine','milestone'].includes(kind)&&!f.name?.trim())throw new Error('请填写名称。');if(kind==='profile'&&f.birth>today)throw new Error('出生日期不能晚于今天。');if(['growth','tooth'].includes(kind)||(kind==='milestone'&&f.day)){if(f.day<profile.value.birth||f.day>today)throw new Error('记录日期须在出生日期与今天之间。');}if(kind==='growth'&&(!(Number(f.height)>0)||!(Number(f.weight)>0)))throw new Error('请填写大于 0 的身高和体重。');if(kind==='ledger'&&!cats.value.find(x=>x.id===f.category&&x.type===f.type))throw new Error('请选择对应的收支分类。');if(kind==='vaccine'&&f.status==='done'&&(!f.given||f.given>today||f.given<profile.value.birth))throw new Error('请填写出生日期至今天之间的接种日期。');if(kind==='category'&&cats.value.some(x=>x.name===f.name.trim()&&x.type===f.type&&x.id!==f.id))throw new Error('同一类型下已有这个分类。');}
function submitChecked(e){const el=e.target.closest('form');if(el?.reportValidity())submit();}
function enterSubmit(e){if(e.key==='Enter'&&e.target.tagName!=='TEXTAREA'&&e.target.tagName!=='BUTTON'){e.preventDefault();submitChecked(e);}}
async function submit(){const kind=modal.value.kind;busy.value=true;formError.value='';try{const f={...form.value};validate(f,kind);if(f.name)f.name=f.name.trim();if(kind==='growth'){f.height=Number(f.height);f.weight=Number(f.weight);}if(kind==='ledger'){f.cents=cents(f.amount);delete f.amount;const cat=cats.value.find(x=>x.id===f.category);f.categoryName=cat.name;f.icon=cat.icon;}if(kind==='vaccine'&&f.status==='pending')f.given='';f.id=kind==='profile'?'profile':kind==='tooth'?'tooth-'+f.number:kind==='meal'?'meal-'+f.day:(f.id||uid());f.kind=kind;f.day||='';await save(f);modal.value=null;toast('已保存');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
async function toggleTodo(item){if(busy.value)return;busy.value=true;try{await save({...item,done:!item.done});}catch(e){toast(e.message);}finally{busy.value=false;}}
function toothClick(number){open('tooth',teeth.value.find(x=>x.number===number)||{number});}
function toothLayout(upper){const nums=upper?['55','54','53','52','51','61','62','63','64','65']:['85','84','83','82','81','71','72','73','74','75'];return nums.map((number,i)=>{const theta=Math.PI-i*Math.PI/9;return {number,x:210+153*Math.cos(theta),y:upper?159-99*Math.sin(theta):215+99*Math.sin(theta),rotation:upper?(i-4.5)*15:-(i-4.5)*15,erupted:teeth.value.some(x=>x.number===number)};});}
const toothShape=n=>+n[1]>=4?'M-17,-14 Q-18,-24 -7,-21 Q0,-17 7,-21 Q18,-24 17,-14 L16,12 Q13,24 6,20 Q0,15 -6,20 Q-14,24 -16,12 Z':+n[1]===3?'M-14,-12 Q-14,-20 0,-25 Q14,-20 14,-12 L11,17 Q0,24 -11,17 Z':'M-15,-18 Q0,-23 15,-18 L13,16 Q0,23 -13,16 Z';
function reset(){resetDemo();toast('已恢复示例');}
function handleEscape(e){if(e.key==='Escape')close();if(e.key==='Tab'&&modal.value){const nodes=[...document.querySelectorAll('.dialog button,.dialog input,.dialog select,.dialog textarea')].filter(x=>!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
onMounted(async()=>{window.addEventListener('hashchange',routeChanged);document.addEventListener('keydown',handleEscape);await init();if(!state.error&&!records('profile').length)editProfile();});
onUnmounted(()=>{window.removeEventListener('hashchange',routeChanged);document.removeEventListener('keydown',handleEscape);clearTimeout(toastTimer);});
</script>

<template>
<div class="app-shell" @click="followLink">
 <aside class="sidebar"><a href="#/" class="brand"><span class="brand-icon"><CuteIcon value="🌱"/></span><div>宝贝成长记<small>LITTLE MOMENTS</small></div></a><p class="sidebar-caption">陪伴每一点成长</p><nav><a href="#/" :class="{active:route==='home'}"><span>⌂</span> 成长首页</a><a v-for="x in features" :key="x[0]" :href="'#/'+x[0]" :class="{active:route===x[0]}"><span><CuteIcon :value="x[1]"/></span>{{x[2]}}</a><a href="#/settings" :class="{active:route==='settings'}"><span>⚙</span> 宝宝档案</a></nav><div class="sidebar-footer"><span><CuteIcon value="☀️"/></span><p>小小的日常<br>是大大的幸福</p><small>用心记录，慢慢长大</small></div></aside>
 <main>
  <div v-if="isDemo" class="demo-bar"><span>示例体验，数据仅保留在本页</span><button @click="reset">恢复示例</button></div>
  <header class="topbar"><div><span class="eyebrow">OUR LITTLE STORY</span><h1 v-if="route==='home'">把长大的每一天，好好收藏<span class="small-flower">✿</span></h1><div v-else class="page-heading"><button class="back-button" @click="back" :aria-label="route==='categories'?'返回账本':'返回首页'">‹</button><h1>{{title}}</h1></div></div><button class="profile-chip" @click="editProfile"><span><CuteIcon value="🐣"/></span><b>{{profile.name}}</b><span class="desktop-only">的成长手记</span></button></header>
  <div v-if="state.loading" class="loading card">🌱 正在翻开宝宝的成长手记…</div>
  <div v-else-if="state.error" class="card error-state"><h2>暂时没有连上成长手记</h2><p>{{state.error}}</p><button class="primary" @click="init">重新连接</button></div>
  <template v-else>
  <template v-if="route==='home'">
   <section class="baby-hero"><div class="hero-copy"><span class="pill">HELLO, LITTLE ONE</span><h2>{{profile.name}}<span>，你好呀</span><i>♡</i></h2><p>世界因为有了你，每一天都变得不一样。</p><div class="hero-info"><div><small>已经来到这个世界</small><b>{{profile.birth?ageLabel(profile.birth):'完善宝宝档案'}} <span>啦</span></b></div><div><small>出生日期</small><b>{{profile.birth||'尚未设置'}}</b></div></div><button class="text-button" @click="editProfile">编辑宝宝档案 <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><span class="spark s1">✧</span><span class="spark s2">✦</span><span class="spark s3">♡</span><div class="rainbow"><i></i><i></i><i></i></div><div class="bear"><i class="ear left"></i><i class="ear right"></i><div class="bear-head"><i class="eye left"></i><i class="eye right"></i><i class="cheek left"></i><i class="cheek right"></i><div class="muzzle"><i></i><span>ᴗ</span></div></div><div class="bear-body"><span>♡</span></div><i class="paw left"></i><i class="paw right"></i></div><span class="little-cloud">☁</span></div></section>
   <div class="section-heading"><div><h2>成长的每一面<span class="heading-dot"></span></h2><p>那些平凡又珍贵的小事</p></div><span class="muted desktop-only">一点一滴，都是爱的印记</span></div>
   <section class="feature-grid"><a v-for="x in features" :key="x[0]" :href="'#/'+x[0]" :class="['feature-card',x[4]]"><div class="feature-icon"><CuteIcon :value="x[1]"/></div><div><h3>{{x[2]}}</h3><p>{{x[3]}}</p></div><span class="feature-arrow">↗</span></a></section>
   <div class="home-bottom"><section class="card today-card"><div class="section-heading compact"><div><h2>今天的小计划 <span class="count">{{todayTodos.length}}</span></h2><p>{{pretty(today)}}</p></div><button class="text-button" @click="go('todos')">全部事项 ↗</button></div><div v-if="todayTodos.length" class="progress-line"><div><i :style="{width:todoProgress+'%'}"></i></div><small>{{todoProgress}}% 已完成</small></div><div v-for="item in todayTodos" :key="item.id" class="todo-row"><button :class="['check',{checked:item.done}]" :aria-label="(item.done?'取消完成':'完成')+item.name" :disabled="busy" @click="toggleTodo(item)">{{item.done?'✓':''}}</button><button class="row-main" @click="open('todo',item)"><b :class="{done:item.done}">{{item.name}}</b><small>{{item.note||'给今天留一点期待'}}</small></button><time>{{item.time}}</time></div><p v-if="!todayTodos.length" class="empty">今天还没有安排，留一点时间陪陪宝宝吧。</p><button class="add-dashed" @click="open('todo',{day:today})">＋ 添加今日事项</button></section><section class="card memory-card"><span class="eyebrow">GROWING, DAY BY DAY</span><h2>小小的你，又长大了一点</h2><div class="mini-stats"><div><span><CuteIcon value="📏"/></span><b>{{latest?.height||'—'}}<small> cm</small></b><p>最近身高</p></div><div><span><CuteIcon value="⚖️"/></span><b>{{latest?.weight||'—'}}<small> kg</small></b><p>最近体重</p></div></div><div class="memory-bottom"><span>🏆 已收藏 {{doneMilestones.length}} 个第一次</span><button class="text-button" @click="go('milestones')">去看看 ↗</button></div><p class="tiny-quote">“你慢慢长大，我慢慢记下。”</p></section></div>
  </template>

  <template v-else-if="route==='growth'">
   <div class="page-intro"><p>每一次测量，都看得见成长。</p><button class="primary" @click="open('growth')">＋ 记录身高体重</button></div>
   <div class="two-columns"><section class="card"><div class="section-heading compact"><h2>成长曲线</h2><div class="segmented"><button :class="{active:growthType==='height'}" @click="growthType='height'">身高</button><button :class="{active:growthType==='weight'}" @click="growthType='weight'">体重</button></div></div><GrowthChart :records="growth" :profile="profile" :type="growthType"/><p class="muted small">{{growthType==='height'?'2 岁前测量身长（平卧），2 岁起测量身高（站立）。':'单位：千克；各测量日期按当天月龄对照。'}}</p></section><section class="card reference-card"><span class="eyebrow">GROWTH REFERENCE</span><h2>最近一次的成长参考</h2><template v-if="latest"><p class="muted">{{latest.day}} · {{ageLabel(profile.birth,latest.day)}}</p><div v-for="type in ['height','weight']" :key="type" class="reference-row"><span>{{type==='height'?'身高 / 身长':'体重'}}</span><b>{{latest[type]}} {{type==='height'?'cm':'kg'}}</b><template v-if="reference(profile.sex,profile.birth,latest.day,type,latest[type])"><span class="tag">{{reference(profile.sex,profile.birth,latest.day,type,latest[type]).label}}</span><small>参考范围：{{reference(profile.sex,profile.birth,latest.day,type,latest[type]).range.join('–')}} {{type==='height'?'cm':'kg'}}<br>{{reference(profile.sex,profile.birth,latest.day,type,latest[type]).month}} 月龄档 · P3–P97</small></template><small v-else>参考适用于已填写性别、出生日期的 0–83 月龄宝宝。</small></div></template><p v-else class="empty">添加一条测量记录后查看。</p></section></div>
   <section class="card list-section"><div class="section-heading compact"><h2>测量记录</h2><span class="muted">{{growth.length}} 次记录</span></div><div v-for="item in growth" :key="item.id" class="record-row"><span class="row-icon peach"><CuteIcon value="📏"/></span><div class="row-main"><b>{{item.day}}</b><small>{{item.note||ageLabel(profile.birth,item.day)}}</small></div><div class="measure"><b>{{item.height}}<small> cm</small></b><b>{{item.weight}}<small> kg</small></b></div><button class="icon-button" :aria-label="'编辑测量 '+item.day" @click="open('growth',item)">✎</button><button class="icon-button danger" :aria-label="'删除测量 '+item.day" @click="askDelete(item)">×</button></div><p v-if="!growth.length" class="empty">第一条成长记录，等你来写。</p></section>
   <aside class="source-note"><b>参考说明</b><p>数据来自国家卫生健康委 <a href="https://www.nhc.gov.cn/wjw/c100311/202211/923e7646561d4b88b72da9097d4da4d5.shtml" target="_blank" rel="noopener">《7 岁以下儿童生长标准》WS/T 423—2022</a> 附录 A.1–A.4。按性别和已满月龄查表；2 岁起按已达到的三个月龄档展示，不做插值。档位依次为下、中下、中、中上、上，P3–P97 为生长水平参考区间。年龄别体重较高不等于超重或肥胖；本页用于日常记录，有疑问请咨询儿保医生。</p></aside>
  </template>

  <template v-else-if="route==='meals'">
   <div class="page-intro"><p>一口一口，认识这个有滋有味的世界。</p><div class="segmented"><button :class="{active:mealWeek}" @click="mealWeek=true">周视图</button><button :class="{active:!mealWeek}" @click="mealWeek=false">月视图</button></div></div>
   <div class="two-columns"><section class="card"><Calendar :model-value="mealDate" :week="mealWeek" :marked="records('meal').map(x=>x.day)" @update:model-value="d=>{mealDate=d;open('meal',records('meal').find(x=>x.day===d))}"/><p class="small muted">点击日期，为宝宝安排一日辅食。</p></section><section class="card"><div class="section-heading compact"><div><h2>{{mealDate===today?'今天吃什么':mealDate}}</h2><p>{{pretty(mealDate)}}</p></div><button class="text-button" @click="open('meal',meal)">编辑 ✎</button></div><div v-for="[key,icon,label] in [['breakfast','🌤','早餐'],['lunch','☀️','午餐'],['dinner','🌙','晚餐'],['fruit','🍎','水果']]" :key="key" class="meal-row"><span class="row-icon yellow"><CuteIcon :value="icon"/></span><div><small>{{label}}</small><b>{{meal?.[key]||'还没安排'}}</b></div></div><button v-if="meal" class="text-button danger" @click="askDelete(meal)">删除当天辅食安排</button></section></div>
   <section class="card list-section"><div class="section-heading compact"><div><h2>食物尝试手记</h2><p>记下尝试结果，准备下一顿更安心。</p></div><button class="primary" @click="open('food')">＋ 添加食物</button></div><div class="tabs"><button v-for="[v,t] in [['all','全部'],['safe','已排除过敏'],['allergy','过敏食物']]" :key="v" :class="{active:foodFilter===v}" @click="foodFilter=v">{{t}}</button></div><div v-for="item in foods" :key="item.id" class="record-row"><span class="row-icon" :class="item.status==='safe'?'green':'pink'"><CuteIcon :value="item.status==='safe'?'🥑':'🍓'"/></span><div class="row-main"><b>{{item.name}} <span :class="['tag',item.status==='allergy'?'warning':'']">{{item.status==='safe'?'已排除过敏':'过敏'}}</span></b><small>{{item.day}} · {{item.note||'未填写备注'}}</small></div><button class="icon-button" :aria-label="'编辑食物 '+item.name" @click="open('food',item)">✎</button><button class="icon-button danger" :aria-label="'删除食物 '+item.name" @click="askDelete(item)">×</button></div><p v-if="!foods.length" class="empty">还没有这类食物记录。</p></section>
  </template>

  <template v-else-if="route==='ledger'">
   <div class="page-intro"><p>给宝宝的每一份心意，都记在这里。</p><div class="button-group"><button class="secondary" @click="go('categories')">管理分类</button><button class="primary" @click="open('ledger')">＋ 记一笔</button></div></div>
   <section class="card"><div class="ledger-controls"><div class="segmented"><button v-for="[v,t] in [['day','日'],['week','周'],['month','月'],['year','年'],['custom','自定义']]" :key="v" :class="{active:ledgerMode===v}" @click="ledgerMode=v">{{t}}</button></div><input v-if="ledgerMode!=='custom'" aria-label="统计日期" type="date" v-model="ledgerAnchor"><div v-else class="date-range"><input aria-label="开始日期" type="date" v-model="customStart"><span>至</span><input aria-label="结束日期" type="date" v-model="customEnd"></div></div><p v-if="!accountingValid" class="error-message">结束日期不能早于开始日期。</p><p class="muted small">{{accountingPeriod.a}} 至 {{accountingPeriod.b}} · 人民币</p><div class="ledger-summary"><div><small>总支出</small><b>¥ {{money(stats.expense)}}</b></div><div><small>总收入</small><b class="income">¥ {{money(stats.income)}}</b></div><div><small>结余</small><b>¥ {{money(stats.income-stats.expense)}}</b></div></div><div class="comparison"><span>↗ 支出环比</span><b>{{stats.change===null?(stats.expense?'上期无支出，无法计算':'暂无对比'):((stats.change>=0?'+':'')+stats.change.toFixed(1)+'%')}}</b><small>上期 {{accountingPeriod.prevA}} 至 {{accountingPeriod.prevB}} · ¥{{money(stats.previous)}}</small></div></section>
   <div class="two-columns list-section"><section class="card"><div class="section-heading compact"><h2>分类排行</h2><div class="segmented"><button :class="{active:ledgerType==='expense'}" @click="ledgerType='expense'">支出</button><button :class="{active:ledgerType==='income'}" @click="ledgerType='income'">收入</button></div></div><div v-for="(item,i) in ranking" :key="item.name" class="ranking-row"><span class="rank">{{i+1}}</span><span class="row-icon yellow"><CuteIcon :value="item.icon"/></span><div class="row-main"><div class="ranking-label"><b>{{item.name}}</b><span>¥{{money(item.sum)}}</span></div><div class="rank-bar"><i :style="{width:(item.sum/ranking[0].sum*100)+'%'}"></i></div></div></div><p v-if="!ranking.length" class="empty">这个区间还没有{{ledgerType==='expense'?'支出':'收入'}}。</p></section><section class="card"><div class="section-heading compact"><h2>收支明细</h2><span class="muted">{{ledgerItems.length}} 笔</span></div><div v-for="item in ledgerItems" :key="item.id" class="record-row ledger-row"><span class="row-icon pink"><CuteIcon :value="item.icon"/></span><div class="row-main"><b>{{item.categoryName}}</b><small>{{item.day}} {{item.note?'· '+item.note:''}}</small></div><b :class="{income:item.type==='income'}">{{item.type==='income'?'+':'−'}}{{money(item.cents)}}</b><button class="icon-button" :aria-label="'编辑账目 '+item.note" @click="open('ledger',item)">✎</button><button class="icon-button danger" :aria-label="'删除账目 '+item.note" @click="askDelete(item)">×</button></div><p v-if="!ledgerItems.length" class="empty">这个区间没有账目。</p></section></div>
  </template>

  <template v-else-if="route==='categories'">
   <div class="page-intro"><p>选择可爱的图标，建立自己的一级分类。</p><button class="primary" @click="open('category')">＋ 添加分类</button></div><section v-for="[type,label] in [['expense','支出分类'],['income','收入分类']]" :key="type" class="card list-section"><h2>{{label}}</h2><div class="category-grid"><div v-for="item in cats.filter(x=>x.type===type)" :key="item.id" class="category-item"><span class="feature-icon yellow"><CuteIcon :value="item.icon"/></span><b>{{item.name}}</b><div><button class="text-button" @click="open('category',item)" :aria-label="'编辑分类 '+item.name">编辑</button><button class="text-button danger" @click="askDelete(item)" :aria-label="'删除分类 '+item.name">删除</button></div></div></div><p class="small muted">删除分类后，已有账目仍保留原分类名称和图标。</p></section>
  </template>

  <template v-else-if="route==='todos'">
   <div class="page-intro"><p>有条不紊地安排，轻轻松松地陪伴。</p><button class="primary" @click="open('todo')">＋ 添加事项</button></div><div class="two-columns"><section class="card"><div class="section-heading compact"><div><h2>{{todoDate===today?'今天的事项':todoDate}}</h2><p>{{pretty(todoDate)}}</p></div><button class="secondary" @click="showTodoCalendar=!showTodoCalendar">{{showTodoCalendar?'收起日历':'展开日历'}} ▦</button></div><Calendar v-if="showTodoCalendar" v-model="todoDate" :marked="records('todo').map(x=>x.day)"/><div v-for="item in todosOn(todoDate)" :key="item.id" class="todo-row"><button :class="['check',{checked:item.done}]" :aria-label="(item.done?'取消完成':'完成')+item.name" :disabled="busy" @click="toggleTodo(item)">{{item.done?'✓':''}}</button><button class="row-main" @click="open('todo',item)"><b :class="{done:item.done}">{{item.name}}</b><small>{{item.time}} {{item.note?'· '+item.note:''}}</small></button><button class="icon-button danger" :aria-label="'删除事项 '+item.name" @click="askDelete(item)">×</button></div><p v-if="!todosOn(todoDate).length" class="empty">这一天还没有事项。</p><button class="add-dashed" @click="open('todo')">＋ 安排一件小事</button></section><section class="card"><h2>未来三日</h2><div v-for="n in 3" :key="n" class="future-day"><div class="future-date"><b>{{['','明天','后天','大后天'][n]}}</b><span>{{pretty(addDays(today,n))}}</span></div><button v-for="item in todosOn(addDays(today,n))" :key="item.id" class="future-item" @click="open('todo',item)"><span>{{item.done?'✓':'○'}} {{item.name}}</span><small>{{item.time}}</small></button><p v-if="!todosOn(addDays(today,n)).length" class="muted small">暂时没有安排</p></div></section></div>
  </template>

  <template v-else-if="route==='vaccines'">
   <div class="page-intro"><p>给健康一份保护，接种的日子不遗漏。</p><button class="primary" @click="open('vaccine')">＋ 新增疫苗</button></div><section class="soft-banner blue"><span><CuteIcon value="🩹"/></span><div><h2>已接种 {{records('vaccine').filter(x=>x.status==='done').length}} 项，待接种 {{pendingVaccines.length}} 项</h2><p>按接种门诊的安排记录，实际接种日期可随时补充。</p></div></section><section class="card list-section"><div class="tabs"><button v-for="[v,t] in [['all','全部记录'],['pending','待接种'],['done','已接种']]" :key="v" :class="{active:vaccineFilter===v}" @click="vaccineFilter=v">{{t}}</button></div><div v-for="item in vaccines" :key="item.id" class="record-row"><span class="row-icon blue"><CuteIcon value="💉"/></span><div class="row-main"><b>{{item.name}}</b><small>{{item.status==='done'?'接种日期：'+item.given:'计划日期：'+item.day}}{{item.note?' · '+item.note:''}}</small></div><span :class="['tag',item.status==='pending'?'warning':'']">{{item.status==='done'?'已接种':'暂未接种'}}</span><button class="icon-button" :aria-label="'编辑疫苗 '+item.name" @click="open('vaccine',item)">✎</button><button class="icon-button danger" :aria-label="'删除疫苗 '+item.name" @click="askDelete(item)">×</button></div><p v-if="!vaccines.length" class="empty">添加需要记录的疫苗，从“暂未接种”开始。</p></section>
  </template>

  <template v-else-if="route==='teeth'">
   <div class="page-intro"><p>小牙齿，大纪念。点击牙齿，记下萌出的日子。</p><span class="tag">已萌出 {{teeth.length}} / 20 颗乳牙</span></div><div class="two-columns"><section class="card tooth-card"><div class="section-heading compact"><h2>宝宝的小牙图</h2><span class="muted small">面对宝宝的视角</span></div><svg viewBox="0 0 420 375" class="tooth-map" aria-label="20颗可点击的乳牙"><defs><linearGradient id="enamel" x1="0" y1="0" x2=".5" y2="1"><stop offset="0" stop-color="#fff"/><stop offset="1" stop-color="#ebe8df"/></linearGradient><filter id="tooth-shadow"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity=".1"/></filter></defs><path d="M50 160 Q50 24 210 26 Q370 24 370 160" fill="none" stroke="#f7ddd6" stroke-width="44" stroke-linecap="round"/><path d="M50 215 Q50 350 210 350 Q370 350 370 215" fill="none" stroke="#f7ddd6" stroke-width="44" stroke-linecap="round"/><text x="210" y="150" text-anchor="middle" class="jaw-label">上颌</text><text x="210" y="243" text-anchor="middle" class="jaw-label">下颌</text><text x="210" y="195" text-anchor="middle" class="tooth-count">{{teeth.length}} 颗小牙萌出啦</text><g v-for="t in [...toothLayout(true),...toothLayout(false)]" :key="t.number" :transform="`translate(${t.x},${t.y}) rotate(${t.rotation})`" role="button" tabindex="0" :aria-label="t.number+'号牙 '+toothInfo(t.number).name+(t.erupted?' 已萌出':' 未记录')" @click="toothClick(t.number)" @keydown.enter.prevent="toothClick(t.number)" @keydown.space.prevent="toothClick(t.number)"><path :d="toothShape(t.number)" :fill="t.erupted?'#dbe5bd':'url(#enamel)'" :stroke="t.erupted?'#92a86a':'#d1ccc2'" stroke-width="1.3" filter="url(#tooth-shadow)"/><path v-if="+t.number[1]>=4" d="M-7,-4 Q0,2 7,-4 M0,0 V8" fill="none" stroke="#cfc9bc"/><text :transform="`rotate(${-t.rotation})`" text-anchor="middle" y="4" class="tooth-number">{{t.erupted?'✓':t.number}}</text></g></svg><div class="chart-legend"><i></i>已萌出 <i class="unrecorded"></i>未记录</div></section><section class="card"><div class="section-heading compact"><h2>萌出手记</h2><span class="muted">按时间排列</span></div><div v-for="item in teeth" :key="item.id" class="record-row"><span class="row-icon purple"><CuteIcon value="🦷"/></span><div class="row-main"><b>{{item.number}} 号 · {{toothInfo(item.number).name}}</b><small>{{item.day}} · {{item.note||'小牙冒头的日子'}}</small></div><button class="icon-button" :aria-label="'编辑牙齿 '+item.number" @click="open('tooth',item)">✎</button><button class="icon-button danger" :aria-label="'删除牙齿 '+item.number" @click="askDelete(item)">×</button></div><p v-if="!teeth.length" class="empty">轻点牙图，记下第一颗小牙。</p></section></div><section class="card list-section"><h2>乳牙萌出时间参考</h2><div class="table-scroll"><table><thead><tr><th>乳牙名称</th><th>上颌（月龄）</th><th>下颌（月龄）</th></tr></thead><tbody><tr v-for="r in [['中切牙','8–12','6–10'],['侧切牙','9–13','10–16'],['第一乳磨牙','13–19','14–18'],['乳尖牙','16–22','17–23'],['第二乳磨牙','25–33','23–31']]" :key="r[0]"><td v-for="s in r" :key="s">{{s}}</td></tr></tbody></table></div><p class="small muted">来源：<a href="https://www.mouthhealthy.org/all-topics-a-z/eruption-charts" target="_blank" rel="noopener">美国牙科协会（ADA）乳牙萌出图</a>。时间有个体差异；此表供记录参考。</p></section>
  </template>

  <template v-else-if="route==='milestones'">
   <div class="page-intro"><p>每一个第一次，都是值得珍藏的小小高光。</p><button class="primary" @click="open('milestone')">＋ 自定义事件</button></div><section class="soft-banner yellow"><span><CuteIcon value="🏆"/></span><div><h2>已收藏 {{doneMilestones.length}} 个第一次</h2><p>按宝宝自己的节奏，慢慢解锁新本领。</p></div></section><div class="tabs milestone-tabs"><button v-for="group in ['全部',...milestoneGroups]" :key="group" :class="{active:milestoneGroup===group}" @click="milestoneGroup=group">{{group}}</button></div><section class="milestone-grid"><article v-for="item in milestones" :key="item.id" :class="['card milestone-card',{achieved:item.day}]"><div class="milestone-top"><span class="row-icon yellow"><CuteIcon :value="item.day?'🏅':{'大运动':'🐾','精细运动':'🖐️','语言':'💬','社交认知':'🌈'}[item.group]"/></span><span class="tag">{{item.group}}</span><button v-if="item.custom" class="icon-button danger" :aria-label="'删除事件 '+item.name" @click="askDelete(item)">×</button></div><h3>{{item.name}}</h3><p>{{item.day?'达成于 '+item.day:'期待这一天'}}</p><small>{{item.note||'每一点进步，都值得被看见。'}}</small><button :class="item.day?'secondary':'add-dashed'" @click="open('milestone',item)">{{item.day?'查看 / 编辑记录':'＋ 记录达成'}}</button></article></section><p v-if="!milestones.length" class="empty">这个分类还没有事件，添加一个吧。</p>
  </template>

  <template v-else-if="route==='settings'"><div class="page-intro"><p>从一个名字开始，写下专属于宝宝的成长手记。</p></div><section class="card profile-card"><span class="profile-avatar"><CuteIcon value="🐣"/></span><h2>{{profile.name}}</h2><p>{{profile.birth?ageLabel(profile.birth):'尚未填写出生日期'}}</p><dl><div><dt>宝宝昵称</dt><dd>{{profile.name}}</dd></div><div><dt>出生日期</dt><dd>{{profile.birth||'未填写'}}</dd></div><div><dt>生长标准参照性别</dt><dd>{{profile.sex==='boy'?'男童':'女童'}}</dd></div></dl><button class="primary" @click="editProfile">编辑宝宝档案</button></section></template>
  <div v-else class="card empty"><h2>这页手记还没写</h2><a href="#/">返回首页</a></div>
  </template>
  <footer class="page-footer"><CuteIcon value="🌱"/> 宝贝成长记 <span>每一天，都值得好好记住。</span></footer>
 </main>
 <nav class="bottom-nav"><a href="#/" :class="{active:route==='home'}"><span>⌂</span>首页</a><a href="#/growth" :class="{active:route==='growth'}"><span>♧</span>成长</a><a href="#/todos" :class="{active:route==='todos'}"><span>☷</span>事项</a><a href="#/settings" :class="{active:route==='settings'}"><span>☺</span>宝宝</a></nav>
 <div v-if="notice" class="toast" role="status">{{notice}}</div>
 <div v-if="modal" class="modal-overlay" @click.self="close"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><div><span class="eyebrow">LITTLE MOMENTS</span><h2 id="dialog-title">{{modal.kind==='delete'?'删除这条记录？':({profile:'宝宝档案',growth:'记录身高体重',meal:'安排一日辅食',food:'记录食物尝试',ledger:'记一笔',category:'编辑分类',todo:'记录每日事项',vaccine:'记录疫苗',tooth:'记录小牙萌出',milestone:'记录成长里程碑'}[modal.kind])}}</h2></div><button class="icon-button" aria-label="关闭弹窗" :disabled="busy" @click="close">×</button></header>
 <template v-if="modal.kind==='delete'"><p>删除后无法恢复。{{modal.record.kind==='category'?'已有账目会保留原分类信息。':''}}</p><p v-if="formError" class="error-message" role="alert">{{formError}}</p><div class="dialog-actions"><button class="secondary" :disabled="busy" @click="close">取消</button><button class="danger-button" :disabled="busy" @click="confirmDelete">{{busy?'正在删除…':'确认删除'}}</button></div></template>
 <form v-else @submit.prevent="submit" @keydown="enterSubmit">
  <fieldset :disabled="busy">
  <template v-if="modal.kind==='profile'"><label>宝宝昵称<input v-model="form.name" maxlength="24" required placeholder="想怎么称呼宝宝？"></label><label>出生日期<input v-model="form.birth" type="date" :max="today" required></label><label>生长标准参照性别<select v-model="form.sex"><option value="girl">女童</option><option value="boy">男童</option></select></label></template>
  <template v-if="modal.kind==='growth'"><label>测量日期<input v-model="form.day" type="date" :min="profile.birth" :max="today" required></label><div class="form-columns"><label>身高 / 身长（cm）<input v-model="form.height" type="number" min="0.1" step="0.1" inputmode="decimal" required placeholder="例如 68.5"></label><label>体重（kg）<input v-model="form.weight" type="number" min="0.01" step="0.01" inputmode="decimal" required placeholder="例如 8.20"></label></div><p class="form-hint">2 岁前量平卧身长，2 岁起量站立身高。</p></template>
  <template v-if="modal.kind==='meal'"><div class="selected-date">📅 {{form.day}} · {{pretty(form.day)}}</div><label v-for="[key,label] in [['breakfast','🌤 早餐'],['lunch','☀️ 午餐'],['dinner','🌙 晚餐'],['fruit','🍎 水果']]" :key="key">{{label}}<input v-model="form[key]" maxlength="160" placeholder="准备吃点什么？"></label></template>
  <template v-if="modal.kind==='food'"><label>食物名称<input v-model="form.name" maxlength="60" required placeholder="例如：南瓜"></label><label>记录日期<input v-model="form.day" type="date" required></label><label>尝试结果<select v-model="form.status"><option value="safe">已排除过敏</option><option value="allergy">过敏</option></select></label></template>
  <template v-if="modal.kind==='ledger'"><div class="segmented form-switch"><button type="button" :class="{active:form.type==='expense'}" @click="form.type='expense';form.category=''">支出</button><button type="button" :class="{active:form.type==='income'}" @click="form.type='income';form.category=''">收入</button></div><label>金额（人民币元）<input v-model="form.amount" type="text" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required placeholder="0.00" class="amount-input"></label><label>分类<select v-model="form.category" aria-label="分类" required><option value="" disabled>选择一个分类</option><option v-for="cat in formCats" :key="cat.id" :value="cat.id">{{cat.icon}} {{cat.name}}</option></select></label><p v-if="!formCats.length" class="form-hint">请先关闭弹窗，在分类管理中添加分类。</p><label>日期<input v-model="form.day" type="date" required></label></template>
  <template v-if="modal.kind==='category'"><label>分类名称<input v-model="form.name" required maxlength="24" placeholder="例如：早教课程"></label><label>收支类型<select v-model="form.type"><option value="expense">支出</option><option value="income">收入</option></select></label><label>选择一个可爱图标</label><div class="icon-picker"><button v-for="ic in categoryIcons" :key="ic" type="button" :aria-label="'选择图标 '+ic" :class="{selected:form.icon===ic}" @click="form.icon=ic"><CuteIcon :value="ic"/></button></div></template>
  <template v-if="modal.kind==='todo'"><label>事项名称<input v-model="form.name" maxlength="80" required placeholder="准备为宝宝做点什么？"></label><div class="form-columns"><label>日期<input v-model="form.day" type="date" required></label><label>时间<input v-model="form.time" type="time"></label></div><label class="checkbox-label"><input type="checkbox" v-model="form.done"> 已完成</label></template>
  <template v-if="modal.kind==='vaccine'"><label>疫苗名称 / 剂次<input v-model="form.name" maxlength="100" required placeholder="例如：乙肝疫苗 · 第 2 剂"></label><label>计划接种日期<input v-model="form.day" type="date" required></label><label>接种状态<select v-model="form.status"><option value="pending">暂未接种</option><option value="done">已接种</option></select></label><label v-if="form.status==='done'">实际接种日期<input v-model="form.given" type="date" :min="profile.birth" :max="today" required></label></template>
  <template v-if="modal.kind==='tooth'"><div class="selected-date">🦷 {{form.number}} 号牙 · {{toothInfo(form.number).name}}</div><label>萌出日期<input v-model="form.day" type="date" :min="profile.birth" :max="today" required></label></template>
  <template v-if="modal.kind==='milestone'"><label>事件名称<input v-model="form.name" required maxlength="60" :readonly="!form.custom"></label><label>事件分类<select v-model="form.group" :disabled="!form.custom"><option v-for="g in milestoneGroups" :key="g">{{g}}</option></select></label><label>达成日期（可留空，表示尚未达成）<input v-model="form.day" type="date" :min="profile.birth" :max="today"></label></template>
  <label v-if="!['profile','category','meal'].includes(modal.kind)">备注（选填）<textarea v-model="form.note" rows="3" maxlength="1000" :placeholder="modal.kind==='tooth'?'例如：流口水多、有些烦躁':'记下一点当时的小细节…'"></textarea></label>
  </fieldset><p v-if="formError" class="error-message" role="alert">{{formError}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="busy" @click="close">取消</button><button type="button" class="primary" :disabled="busy" @click="submitChecked">{{busy?'正在保存…':'保存记录'}}</button></div>
 </form></section></div>
</div>
</template>
